window.kbPageData["views/entry/k-1602beb56b6f992a"] = {"key":"entry/k-1602beb56b6f992a","state":{"route":"entry/k-1602beb56b6f992a"},"node":{"id":"k-1602beb56b6f992a","mode":"k","title":"河长制","type":"制度与规则","domain":"文化","reading":"","intro":"","priority":100,"aliases":["村级河长制通过巡查和综合整治改善河道水质"],"qs":["江苏 2023 A类 申论#1"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"河长制是由各级党政负责人担任河长，负责组织领导相应河湖管理保护工作的责任制度。","review":{"definition":"河长制是由各级党政负责人担任河长，负责组织领导相应河湖管理保护工作的责任制度。","explanation":"材料从古代地方官员承担治水职责写到现代河长负责河湖管护。梅林村由村支书担任村级河长，日常巡查墩子河。当地通过清淤、连通水系和治理污水，使河道恢复畅流，水质由劣Ⅴ类改善到Ⅲ类，河边也成了村民休闲的场所。本题可概括为落实河长制，畅通河道、改善水质、美化环境。","references":[],"evidence":"清淤泥、连水系、治污水，一套组合拳下来，河畅流、水碧清。","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2023 A类 申论#1":{"paper":"江苏 2023 A类 申论","n":1,"mod":"申论","src":["7e42c077e9c847e9914a.pdf",4],"asrc":["e31432d6e63d78de7465.pdf",1],"card":"d1fd3fc017c890db30bdc8ef","links":[{"id":"k-1602beb56b6f992a","role":"直接考查","why":"材料以墩子河说明河长巡查与综合整治如何改善河道和水质。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-1602beb56b6f992a":[["江苏 2023 A类 申论#1"]]}};
